import { useState, useEffect } from 'react';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import SearchIcon from '@mui/icons-material/Search';
import PersonIcon from '@mui/icons-material/Person';
import CloseIcon from '@mui/icons-material/Close';
import api from '../services/api';
import toast from 'react-hot-toast';
import '../styles/dashboard.css';

const roleLabel = { admin: 'مدير', teacher: 'معلم', student: 'طالب' };
const roleColor = { admin: 'badge-red', teacher: 'badge-gold', student: 'badge-green' };

export default function Users() {
  const [users, setUsers] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState('');
  const [modal, setModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({ name: '', email: '', password: '', role: 'student', phone: '' });
  const [saving, setSaving] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const { data } = await api.get('/users', { params: { search, role: roleFilter || undefined } });
      setUsers(data.users); setTotal(data.total);
    } catch { toast.error('فشل تحميل المستخدمين'); } finally { setLoading(false); }
  };

  useEffect(() => { load(); }, [search, roleFilter]);

  const openCreate = () => { setEditing(null); setForm({ name: '', email: '', password: '', role: 'student', phone: '' }); setModal(true); };
  const openEdit = (u) => { setEditing(u); setForm({ name: u.name, email: u.email, password: '', role: u.role, phone: u.phone || '' }); setModal(true); };

  const handleSave = async (e) => {
    e.preventDefault(); setSaving(true);
    try {
      if (editing) { await api.put(`/users/${editing.id}`, form); toast.success('تم التحديث'); }
      else { await api.post('/users', form); toast.success('تم الإنشاء'); }
      setModal(false); load();
    } catch (err) { toast.error(err.response?.data?.message || 'فشل الحفظ'); } finally { setSaving(false); }
  };

  const handleDelete = async (id, name) => {
    if (!window.confirm(`هل تريد حذف "${name}"؟`)) return;
    try { await api.delete(`/users/${id}`); toast.success('تم الحذف'); load(); }
    catch { toast.error('فشل الحذف'); }
  };

  return (
    <div className="fade-in">
      <div className="page-header">
        <div>
          <h1 className="page-title">إدارة المستخدمين</h1>
          <p className="page-breadcrumb">إجمالي: {total} مستخدم</p>
        </div>
        <button className="btn btn-school-primary d-flex align-items-center gap-1" onClick={openCreate}>
          <AddIcon style={{ fontSize: 20 }} /> إضافة مستخدم
        </button>
      </div>

      <div className="school-card mb-4">
        <div className="row g-3 align-items-center">
          <div className="col-md-6">
            <div className="input-icon-wrap">
              <span className="input-icon-right"><SearchIcon style={{ fontSize: 18 }} /></span>
              <input className="school-input input-with-icon-r"
                value={search} onChange={e => setSearch(e.target.value)} />
            </div>
          </div>
          <div className="col-md-3">
            <select className="school-input" value={roleFilter} onChange={e => setRoleFilter(e.target.value)}>
              <option value="">جميع الأدوار</option>
              <option value="admin">مدير</option>
              <option value="teacher">معلم</option>
              <option value="student">طالب</option>
            </select>
          </div>
        </div>
      </div>

      <div className="school-card p-0 overflow-hidden">
        {loading ? <div className="p-5 text-center"><div className="school-spinner" /></div> : (
          <div className="table-wrapper">
            <table className="table school-table mb-0">
              <thead><tr>
                <th>المستخدم</th><th>البريد الإلكتروني</th><th>الدور</th>
                <th>الهاتف</th><th>تاريخ الانضمام</th><th>الإجراءات</th>
              </tr></thead>
              <tbody>
                {users.length === 0 ? (
                  <tr><td colSpan={6} className="text-center p-4" style={{ color: '#9ca3af' }}>لا توجد نتائج</td></tr>
                ) : users.map(u => (
                  <tr key={u.id}>
                    <td>
                      <div className="d-flex align-items-center gap-2">
                        <div style={{ width: 36, height: 36, borderRadius: '50%', background: 'var(--clr-green)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', flexShrink: 0 }}>
                          <PersonIcon style={{ fontSize: 18 }} />
                        </div>
                        <span style={{ fontWeight: 600 }}>{u.name}</span>
                      </div>
                    </td>
                    <td style={{ direction: 'ltr' }}>{u.email}</td>
                    <td><span className={`badge-school ${roleColor[u.role]}`}>{roleLabel[u.role]}</span></td>
                    <td>{u.phone || '—'}</td>
                    <td>{new Date(u.created_at).toLocaleDateString('ar-IQ')}</td>
                    <td>
                      <div className="d-flex gap-2">
                        <button className="btn btn-school-primary btn-sm d-flex align-items-center gap-1" onClick={() => openEdit(u)}>
                          <EditIcon style={{ fontSize: 16 }} />
                        </button>
                        <button className="btn btn-school-danger btn-sm d-flex align-items-center gap-1" onClick={() => handleDelete(u.id, u.name)}>
                          <DeleteIcon style={{ fontSize: 16 }} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {modal && (
        <div className="school-modal-overlay" onClick={() => setModal(false)}>
          <div className="school-modal" onClick={e => e.stopPropagation()}>
            <div className="school-modal-header">
              <span className="school-modal-title">{editing ? 'تعديل مستخدم' : 'إضافة مستخدم جديد'}</span>
              <button className="school-modal-close" onClick={() => setModal(false)}><CloseIcon style={{ fontSize: 18 }} /></button>
            </div>
            <form onSubmit={handleSave}>
              <div className="school-modal-body">
                <div className="row g-3">
                  <div className="col-12">
                    <label className="school-label">الاسم الكامل</label>
                    <input className="school-input" required value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))} />
                  </div>
                  <div className="col-12">
                    <label className="school-label">البريد الإلكتروني</label>
                    <input className="school-input" type="email" required value={form.email} onChange={e => setForm(p => ({ ...p, email: e.target.value }))} style={{ direction: 'ltr' }} />
                  </div>
                  <div className="col-md-6">
                    <label className="school-label">الدور</label>
                    <select className="school-input" value={form.role} onChange={e => setForm(p => ({ ...p, role: e.target.value }))}>
                      <option value="student">طالب</option>
                      <option value="teacher">معلم</option>
                      <option value="admin">مدير</option>
                    </select>
                  </div>
                  <div className="col-md-6">
                    <label className="school-label">الهاتف</label>
                    <input className="school-input" value={form.phone} onChange={e => setForm(p => ({ ...p, phone: e.target.value }))} />
                  </div>
                  <div className="col-12">
                    <label className="school-label">{editing ? 'كلمة مرور جديدة' : 'كلمة المرور'}</label>
                    <input className="school-input" type="password" required={!editing} value={form.password} onChange={e => setForm(p => ({ ...p, password: e.target.value }))} />
                  </div>
                </div>
              </div>
              <div className="school-modal-footer">
                <button type="button" className="btn btn-ghost" onClick={() => setModal(false)}>إلغاء</button>
                <button type="submit" className="btn btn-school-primary" disabled={saving}>
                  {saving ? 'جارٍ الحفظ...' : 'حفظ'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
